const H = 12, W1 = 80, W2 = 90;
function mk(w){ const g=[]; for(let i=0;i<H;i++) g.push(new Array(w).fill(".")); return g; }
function put(g,r,c,ch){ if(g && g[r] && c>=0 && c<g[r].length) g[r][c]=ch; }
function plat(g,r,a,b){ for(let c=a;c<=b;c++) put(g,r,c,"-"); }
function tower(g,r1,r2,a,b){ for(let r=r1;r<=r2;r++) for(let c=a;c<=b;c++) put(g,r,c,"="); }
const g1 = mk(W1);
for(let c=0;c<W1;c++){ put(g1,11,c,"#"); put(g1,10,c,"#"); }
[30,31,52,53,54,68,69].forEach(c=>put(g1,10,c,"."));
plat(g1,8,10,13); plat(g1,8,17,20); plat(g1,7,24,27); plat(g1,7,31,34); plat(g1,6,38,41); plat(g1,7,44,47); plat(g1,8,51,54); plat(g1,7,58,61); plat(g1,6,65,68);
