tower(g2,7,9,28,29); tower(g2,6,9,54,55); tower(g2,6,9,71,72);
plat(g2,8,10,13); plat(g2,7,17,20); plat(g2,6,22,25); plat(g2,5,32,35); plat(g2,5,37,40); plat(g2,6,46,49); plat(g2,5,52,55); plat(g2,6,62,65); plat(g2,5,69,72); plat(g2,6,79,82);
