put(g2,9,24,"C"); put(g2,9,25,"C"); put(g2,8,58,"C"); put(g2,8,59,"C"); put(g2,8,74,"C"); put(g2,8,76,"C");
[50].forEach(c=>{ put(g2,7,c,"W"); put(g2,8,c,"W"); put(g2,9,c,"W"); });
