palette: { sky: "#3D4E9E", skyBottom: "#FF9E6D", ground: "#4B3A5E", groundTop: "#7A5A7A", accent: "#FFE29A", collectible: "#FFE29A", enemy: "#3A3347", hazard: "#FF6B6B", player: "#FFF8E7" },
