"W": { type: "custom", sprite: "updraft", size: 48, touch(e, api){ try{ if(!e || !api || !api.player) return; const p = api.player; if(p.y == null || p.vy == null) return; const g = api.state ? api.state.gravity : 1; if(g > 0){ if(p.vy > -540) p.vy = -540; p.vy -= 14; if(api.state.frame % 12 === 0 && api.burst) api.burst(p.x + 17, p.y + 30, "#FFE29A", 1, 60); } }catch(_){} } }
},
levels: [
{ name: "Chimney Hop Row", rows: rows1, background: "background" },
{ name: "Bell Tower Updrafts", rows: rows2, background: "background" }
],
hooks: {
onUpdate(api){ try{ const p = api.player, s = api.state; if(!p || !s) return; if(s.status !== "playing") return; if(s.gravity < 0) s.gravity = 1; if(!p.onGround && p.vy > 150){ let cap = 150; if(api.powers && api.powers.speed) cap = 85; p.vy += (cap - p.vy) * 0.22; if(s.frame % 22 === 0 && api.burst) api.burst(p.x + 17, p.y + 8, "#FFE29A", 1, 30); } }catch(_){} },
onPowerup(item, api){ try{ if(api && api.floatText && api.player) api.floatText("Tailwind glide!", api.player.x, api.player.y - 30, "#FFE29A"); }catch(_){} },
onStomp(enemy, api){ try{ if(api && api.confetti && enemy) api.confetti(enemy.x + 20, enemy.y); }catch(_){} },
onDraw(ctx, api){ try{ if(api.state.time < 4 && api.state.status === "playing") Siwi.text(ctx, "Hold JUMP to glide - ride golden updrafts", 480, 60, 20, "#FFE29A", "center"); }catch(_){} }
}
